function hexToTriplet(h) {
  h = h.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)).join(' ');
}

/** { '--neutral-50': '250 250 250', ... } untuk satu mode. */
function cssVars(mode) {
  const src = mode === 'dark' ? DARK : LIGHT;
  const out = {};
  for (const k of Object.keys(src)) out['--' + k] = hexToTriplet(src[k]);
  return out;
}

/** Peta hex terang → hex gelap (untuk warna ikon / style inline). */
function hexMap() {
  const m = {};
  for (const k of Object.keys(LIGHT)) {
    // Putih TIDAK dipetakan: ikon/teks putih di atas oranye harus tetap putih.
    if (k === 'card') continue;
    if (LIGHT[k] && DARK[k] && LIGHT[k] !== DARK[k]) m[LIGHT[k].toUpperCase()] = DARK[k];
  }
  return m;
}

module.exports = { LIGHT, DARK, FAMILIES, VAR_SHADES, cssVars, hexMap };
